package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector.MixInResolver;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.reflect.*;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for AnnotatedClass._addFieldMixIns
 */
public class AnnotatedClass__addFieldMixIns_TriageGen1Test {

    // Dummy annotations for testing
    @Retention(RetentionPolicy.RUNTIME)
    @interface TestAnnotation {}

    // Target classes and Mix-ins
    public static class Target {
        public String name;
        public int age;
        public String ignored;
    }

    public static class MixIn {
        @TestAnnotation
        public String name; // Should match Target.name

        @JsonProperty("age_prop")
        public int age; // Should match Target.age

        public String ignored; // Should match Target.ignored

        @SuppressWarnings("unused")
        private String privateField; // Should be ignored if _isIncludableField returns false

        public static String staticField; // Should be ignored by _isIncludableField
    }

    // A subclass of MixIn to test the supertype traversal logic
    public static class SubMixIn extends MixIn {
        @TestAnnotation
        public String newField;
    }

    /**
     * Since _addFieldMixIns is protected, we use a subclass to expose it for testing.
     */
    private static class TestableAnnotatedClass extends AnnotatedClass {
        protected TestableAnnotatedClass(Class<?> cls, com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr, com.fasterxml.jackson.databind.introspect.MixInResolver mir) {
            super(cls, aintr, mir);
        }

        @Override
        public void _addFieldMixIns(Class<?> targetClass, Class<?> mixInCls, Map<String, AnnotatedField> fields) {
            super._addFieldMixIns(targetClass, mixInCls, fields);
        }
    }

    @Test
    public void testAddFieldMixIns_Success() throws Exception {
        // Setup
        AnnotatedClass ac = mock(AnnotatedClass.class);
        // We need a real instance to call the protected method, but we use a spy or a subclass
        // Because the method is protected, we use our TestableAnnotatedClass
        TestableAnnotatedClass testableAc = new TestableAnnotatedClass(Target.class, null, null);

        Map<String, AnnotatedField> fields = new HashMap<>();

        // Mock AnnotatedField objects
        AnnotatedField fieldName = mock(AnnotatedField.class);
        AnnotatedField fieldAge = mock(AnnotatedField.class);
        AnnotatedField fieldIgnored = mock(AnnotatedField.class);
        AnnotatedField fieldNew = mock(AnnotatedField.class);

        fields.put("name", fieldName);
        fields.put("age", fieldAge);
        fields.put("ignored", fieldIgnored);
        fields.put("newField", fieldNew);

        // We need to mock _addOrOverrideAnnotations because it's a protected method within the same class
        // However, since we are testing the logic of the loop and field matching, 
        // we will spy on the testable instance to verify the calls.
        TestableAnnotatedClass spyAc = spy(testableAc);

        // Execute
        spyAc._addFieldMixIns(Target.class, SubMixIn.class, fields);

        // Verify
        // 1. Check if name was processed (from MixIn)
        verify(spyAc)._addOrOverrideAnnotations(eq(fieldName), any());
        // 2. Check if age was processed (from MixIn)
        verify(spyAc)._addOrOverrideAnnotations(eq(fieldAge), any());
        // 3. Check if ignored was processed (from MixIn)
        verify(spyAc)._addOrOverrideAnnotations(eq(fieldIgnored), any());
        // 4. Check if newField was processed (from SubMixIn)
        verify(spyAc)._addOrOverrideAnnotations(eq(fieldNew), any());
    }

    @Test
    public void testAddFieldMixIns_IgnoreNonIncludableAndMissingFields() throws Exception {
        TestableAnnotatedClass testableAc = new TestableAnnotatedClass(Target.class, null, null);
        TestableAnnotatedClass spyAc = spy(testableAc);

        Map<String, AnnotatedField> fields = new HashMap<>();
        AnnotatedField fieldName = mock(AnnotatedField.class);
        fields.put("name", fieldName);

        // Add a field to the map that exists in MixIn but is static (should be ignored by _isIncludableField)
        // Note: We rely on the actual implementation of _isIncludableField in Jackson.
        // Usually, it returns false for static/synthetic.

        // We add a field to the map that is NOT in the MixIn class to test the null check
        AnnotatedField nonExistentField = mock(AnnotatedField.class);
        fields.put("nonExistent", nonExistentField);

        // Execute
        spyAc._addFieldMixIns(Target.class, MixIn.class, fields);

        // Verify
        verify(spyAc, atLeastOnce())._addOrOverrideAnnotations(eq(fieldName), any());
        // Verify that _addOrOverrideAnnotations was never called for the non-existent field
        verify(spyAc, never())._addOrOverrideAnnotations(eq(nonExistentField), any());
        // Verify static field was not processed (assuming _isIncludableField returns false for static)
        // MixIn.staticField is static.
    }

    @Test
    public void testAddFieldMixIns_NoMixInFieldsMatch() throws Exception {
        TestableAnnotatedClass testableAc = new TestableAnnotatedClass(Target.class, null, null);
        TestableAnnotatedClass spyAc = spy(testableAc);

        Map<String, AnnotatedField> fields = new HashMap<>();
        AnnotatedField unrelatedField = mock(AnnotatedField.class);
        fields.put("unrelated", unrelatedField);

        // Execute
        spyAc._addFieldMixIns(Target.class, MixIn.class, fields);

        // Verify
        verify(spyAc, never())._addOrOverrideAnnotations(any(), any());
    }
}
